"""Write `scope.json`: what this run promises to document, and why each other file is not.

    python3 scripts/build_scope.py --index .docs-build/structure.json --root . \\
        --out .docs-build/scope.json

Every file the scanner found gets a disposition (`product`, `test`, `generated`, `vendor`,
`asset`, `empty`) and, for anything that is not product, the rule that put it there. The
classification is mechanical so that it is the same on every run; the person who reads it at
checkpoint P1 is there to disagree with a rule, not to redo the sorting.

**No bare substring match on `test`.** `src/latest/` and `contest.py` are product source.
A file is a test because the scanner says so (`is_test`: a `tests/` directory or a
`test_*`/`*_test` name), and the row says which of those it was.

What the rules look at, in the order they apply:

    test        the scanner's `is_test`
    vendor      a path component naming a vendored tree (`vendor/`, `third_party/` ...)
    generated   a generated-file naming convention (`*_pb2.py`, `*.pb.go` ...), or a
                marker in the first lines of the file (`@generated`, `DO NOT EDIT` ...)
    asset       example or documentation-tooling source, and every non-source file the
                scanner inventoried (README, CI, packaging, configuration)
    empty       checked last, and only for a file that would otherwise be product: zero
                bytes or only whitespace. A comment, a docstring or an import is not empty
    product     everything else

Reading state starts `unread` for product and `excluded` for the rest. A file already in an
earlier `scope.json` keeps its state while its content is unchanged, so running the survey
again does not forget what was read.

`product_roots` are the directories that hold the product files, nested ones folded into their
parent. They come from the classification and not from the reading shortlist: a shortlist is
a batch, and a root that only the first batch reached would say the product ends there.
`required_topics` are the chosen template's question ids (`question:<id>`) when a template
is recorded, and a `feature:<area>` for each area of a feature map when one is given. A
feature map is a checklist of what the product does, never evidence: it only adds topics
and groups the files an area owns into one reading task.

Reads the working tree (the first kilobytes of each source file, to find a generated-file
marker); writes only --out. Standard library only.

Exit codes: 0 written, 2 input error, 3 internal error.
"""

import argparse
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import scope_record  # noqa: E402

VENDOR_DIRS = {"vendor", "third_party", "third-party", "thirdparty", "node_modules",
               "site-packages", "bower_components", "extern", "externals"}
EXAMPLE_DIRS = {"examples", "example", "samples", "sample"}
DOC_TOOL_DIRS = {"docs", "doc"}

# Written by a tool, named so. Matched on the file name alone.
GENERATED_NAMES = (
    (re.compile(r"_pb2(_grpc)?\.pyi?$"), "protobuf output (*_pb2.py)"),
    (re.compile(r"\.pb\.go$"), "protobuf output (*.pb.go)"),
    (re.compile(r"\.pb\.(cc|h)$"), "protobuf output (*.pb.cc/h)"),
    (re.compile(r"[._]generated\.\w+$"), "named *.generated.* or *_generated.*"),
    (re.compile(r"\.min\.(js|css)$"), "minified output (*.min.*)"),
)

# A marker a generator writes at the top of its output. Looked for in the first lines only:
# a comment further down is as likely to be a mention of the convention as an instance.
# The anchored patterns are per line (re.M): the header is several lines, and a shebang,
# an encoding line or a copyright line commonly comes before the generator's own.
GENERATED_MARKERS = (
    (re.compile(r"@generated\b"), "carries an @generated marker"),
    (re.compile(r"\bcode generated\b.*\bdo not edit\b", re.I), "carries a 'Code generated ... DO NOT EDIT' header"),
    (re.compile(r"^\W*(?:this file (?:is|was) )?(?:auto-?generated|automatically generated)\b",
                re.I | re.M), "says it is auto-generated"),
    (re.compile(r"\bgenerated by\b.{0,60}\bdo not (?:edit|modify)\b", re.I),
     "says it is generated and not to be edited"),
    (re.compile(r"^\W*do not edit\b.{0,40}\bgenerated\b", re.I | re.M),
     "says it is generated and not to be edited"),
)
EMPTY_REASON = "empty file: nothing to read or cite"
HEADER_LINES = 8
HEADER_BYTES = 2048


def fail(message, code=2):
    sys.stderr.write("FAIL  %s\n" % message)
    return code


def read_header(root_real, rel_path):
    """The first lines of a file, or '' when it cannot be read or leaves the root.

    Resolved and checked for containment: a symlink named like source must not make this
    read something outside the repository being documented.
    """
    full = os.path.realpath(os.path.join(root_real, rel_path))
    if full != root_real and not full.startswith(root_real + os.sep):
        return ""
    try:
        with open(full, "rb") as fh:
            data = fh.read(HEADER_BYTES)
    except OSError:
        return ""
    return "\n".join(data.decode("utf-8", errors="replace").splitlines()[:HEADER_LINES])


def is_empty(root_real, rel_path):
    """True when the file is zero bytes or only whitespace.

    Contained in the root like `read_header`. Reads at most HEADER_BYTES + 1 bytes, so a
    file longer than that is never empty. A file that cannot be read is not empty: it
    stays product, as it did before this rule existed.
    """
    full = os.path.realpath(os.path.join(root_real, rel_path))
    if full != root_real and not full.startswith(root_real + os.sep):
        return False
    try:
        with open(full, "rb") as fh:
            data = fh.read(HEADER_BYTES + 1)
    except OSError:
        return False
    return len(data) <= HEADER_BYTES and not data.strip()


def classify(record, root_real):
    """(disposition, reason) for one parsed source file. Reason is '' for product."""
    path = record["path"]
    parts = path.split("/")
    directories, name = parts[:-1], parts[-1]
    lowered = [d.lower() for d in directories]

    if record.get("is_test"):
        # Name the rule the scanner applied, so the row can be argued with.
        for directory in directories:
            if directory.lower() in ("test", "tests", "spec", "specs", "__tests__",
                                     "testing"):
                return "test", "scanner marks it a test: it sits under %s/" % directory
        return "test", "scanner marks it a test by its file name (%s)" % name
    for directory in directories:
        if directory.lower() in VENDOR_DIRS:
            return "vendor", "third-party code under %s/" % directory
    for pattern, why in GENERATED_NAMES:
        if pattern.search(name):
            return "generated", why
    header = read_header(root_real, path)
    for pattern, why in GENERATED_MARKERS:
        if pattern.search(header):
            return "generated", "the file %s" % why
    for directory in directories:
        if directory.lower() in EXAMPLE_DIRS:
            return "asset", "example source under %s/" % directory
    if lowered and lowered[0] in DOC_TOOL_DIRS:
        return "asset", "documentation tooling under %s/" % directories[0]
    if is_empty(root_real, path):
        return "empty", EMPTY_REASON
    return "product", ""


def roots_of(product_paths):
    """The directories that hold the product modules, nested ones folded into their parent.

    A file at the repository root contributes `.`, which stands for those files alone: it
    does not swallow every other root, or the list would say nothing.
    """
    directories = {os.path.dirname(p) or "." for p in product_paths}
    named = sorted(d for d in directories if d != ".")
    kept = [d for d in named
            if not any(d != other and d.startswith(other + "/") for other in named)]
    return (["."] if "." in directories else []) + kept


def glob_regex(pattern):
    """A path glob as a regex: `**` crosses directories, `*` and `?` do not."""
    pattern = pattern.strip()
    if pattern.startswith("./"):
        pattern = pattern[2:]
    if pattern.endswith("/"):
        pattern += "**"
    out, i = "", 0
    while i < len(pattern):
        char = pattern[i]
        if pattern[i:i + 3] == "**/":
            out += "(?:.*/)?"
            i += 3
        elif pattern[i:i + 2] == "**":
            out += ".*"
            i += 2
        elif char == "*":
            out += "[^/]*"
            i += 1
        elif char == "?":
            out += "[^/]"
            i += 1
        else:
            out += re.escape(char)
            i += 1
    return re.compile("^" + out + "$")


def owned_by(path, area):
    return any(glob_regex(g).match(path) for g in area.get("owns", ()))


def template_topics(template):
    """`question:<id>` for every question the recorded template asks."""
    topics = []
    if isinstance(template, dict) and template.get("kind") == "questions":
        for page in template.get("pages", ()) or ():
            for question in page.get("questions", ()) or ():
                if isinstance(question, dict) and question.get("id"):
                    topics.append("question:%s" % question["id"])
    return sorted(set(topics))


def build(index, root, template=None, feature_map=None, previous=None):
    root_real = os.path.realpath(root)
    earlier = {row["path"]: row for row in (previous or {}).get("files", ()) or ()
               if isinstance(row, dict) and row.get("path")}
    entries = {e.get("path") if isinstance(e, dict) else e
               for e in index.get("entry_points", ()) or ()}
    areas = [a for a in (feature_map or {}).get("areas", ()) or () if a.get("name")]

    rows = []
    for record in index.get("files", ()):
        disposition, reason = classify(record, root_real)
        row = {"path": record["path"], "disposition": disposition}
        if disposition == "product":
            row["reading"] = "unread"
            row["symbols"] = len(record.get("symbols") or ())
            row["source_hash"] = record.get("source_hash")
            if record["path"] in entries:
                row["entry_point"] = True
            before = earlier.get(record["path"])
            # Kept only while the file is the one that was read: a changed file is unread
            # again, however recently someone looked at the old one.
            if (before and before.get("disposition") == "product"
                    and before.get("source_hash") == record.get("source_hash")
                    and before.get("reading") in ("read", "analyzed")):
                row["reading"] = before["reading"]
            owning = [a["name"] for a in areas if owned_by(record["path"], a)]
            if owning:
                row["features"] = owning
                row["task"] = "feature:%s" % owning[0]
        else:
            row["reading"] = "excluded"
            row["reason"] = reason
        rows.append(row)
    for asset in index.get("assets", ()) or ():
        rows.append({"path": asset["path"], "disposition": "asset",
                     "reading": "excluded",
                     "reason": "%s: inventoried for citing, not parsed as source"
                               % asset.get("kind", "file")})

    # A person's change at P1 outlives a rerun: re-classifying mechanically would undo it.
    by_path = {row["path"]: row for row in rows}
    for path, before in earlier.items():
        row = by_path.get(path)
        # Only a person writes it, and it changes neither disposition nor reading.
        if row is not None and before.get("undocumented"):
            row["undocumented"] = before["undocumented"]
        if row is None or not before.get("override"):
            continue
        row["override"] = before["override"]
        row["disposition"] = before.get("disposition", row["disposition"])
        if row["disposition"] == "product":
            row["reading"] = before.get("reading") if before.get("reading") in (
                "read", "analyzed") else "unread"
            row.pop("reason", None)
        else:
            row["reading"] = "excluded"
            row["reason"] = (before.get("reason")
                             or "changed by a person: %s" % before["override"])

    rows.sort(key=lambda r: r["path"])
    product = [r["path"] for r in rows if r["disposition"] == "product"]
    topics = template_topics(template) + ["feature:%s" % a["name"] for a in areas]
    return {
        "scope_version": scope_record.SCOPE_VERSION,
        "index_hash": index.get("index_hash"),
        "product_roots": roots_of(product),
        "required_topics": sorted(set(topics)),
        "files": rows,
    }


def load_json(path, label):
    if not path:
        return None, None
    if not os.path.isfile(path):
        return None, "no such %s: %s" % (label, path)
    try:
        with open(path, encoding="utf-8") as fh:
            return json.load(fh), None
    except (OSError, ValueError) as exc:
        return None, "cannot read %s: %s" % (path, exc)


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--index", required=True, help="path to structure.json")
    parser.add_argument("--root", default=".", help="the repository being documented")
    parser.add_argument("--out", default=".docs-build/scope.json")
    parser.add_argument("--template", help="template.json, when the user has chosen one")
    parser.add_argument("--feature-map", help="feature-map.json from read_feature_map.py")
    args = parser.parse_args()

    index, error = load_json(args.index, "index")
    if error or index is None:
        return fail(error or "--index is required")
    if index.get("schema_version") not in (2, 3):
        return fail("unsupported index schema_version %r" % index.get("schema_version"))
    if not os.path.isdir(args.root):
        return fail("no such directory: %s" % args.root)
    template, error = load_json(args.template if args.template and
                                os.path.isfile(args.template) else None, "template")
    if error:
        return fail(error)
    # Absent is the ordinary case -- most repositories have no feature map -- and the survey
    # names the path whether or not `read_feature_map.py` wrote one.
    feature_map, error = load_json(args.feature_map if args.feature_map and
                                   os.path.isfile(args.feature_map) else None, "feature map")
    if error:
        return fail(error)
    previous = scope_record.load(args.out) if os.path.isfile(args.out) else None

    scope = build(index, args.root, template, feature_map, previous)
    problem = scope_record.malformed(scope)
    if problem:
        return fail("the scope built here is not valid: %s" % problem, 3)

    directory = os.path.dirname(os.path.abspath(args.out))
    os.makedirs(directory, exist_ok=True)
    temporary = args.out + ".tmp"
    with open(temporary, "w", encoding="utf-8") as fh:
        json.dump(scope, fh, indent=1, sort_keys=True)
        fh.write("\n")
    os.replace(temporary, args.out)

    counts = {}
    for row in scope["files"]:
        counts[row["disposition"]] = counts.get(row["disposition"], 0) + 1
    print("scope: %s" % ", ".join("%d %s" % (counts[d], d)
                                  for d in scope_record.DISPOSITIONS if counts.get(d)))
    print("product roots: %s" % ", ".join(scope["product_roots"]))
    if scope["required_topics"]:
        print("required topics: %d (%s)" % (len(scope["required_topics"]),
                                            ", ".join(scope["required_topics"][:5])))
    symbol_free = len(scope_record.symbol_free(scope))
    if symbol_free:
        print("%d product file(s) define no symbol; each still gets a reading task "
              "(what the file does, in one statement)" % symbol_free)
    print("wrote %s" % args.out)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as exc:  # noqa: BLE001
        sys.stderr.write("ERROR %s\n" % exc)
        sys.exit(3)
